def main():
    assert len(QUESTIONS) == 15
    assert len({q["id"] for q in QUESTIONS}) == 15
    for question in QUESTIONS:
        assert len(question["options"]) == len(set(question["options"])) == len(question["optionExplanations"]) == 5
        assert question["answer"] == question["options"][question["answerIndex"]]
        assert question["leadIn"].endswith("?")
        assert len(question["disciplines"]) >= 2
        assert question["references"] and all(r.get("pdfPages") or r.get("url") for r in question["references"])
    destination = ROOT / "data/usmle-module-bank.json"
    bank = json.loads(destination.read_text(encoding="utf-8")) if destination.exists() else {
        "schemaVersion": 1,
        "title": "USMLE Step 1 Integrated Modules",
        "modules": [{"id": f"usmle-module-{n:02d}", "moduleNumber": n, "title": f"Module {n}", "questions": []} for n in range(1, 11)],
    }
    module = next(m for m in bank["modules"] if m["id"] == MODULE_ID)
    module["questions"] = QUESTIONS
    destination.write_text(json.dumps(bank, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"Built {len(QUESTIONS)} integrated questions in Module 1; all other modules preserved.")


if __name__ == "__main__":
    main()
